mapper.select:
SELECT m.id AS merchant_id, m.name AS merchant_name, m.category, m.latitude, m.longitude
  FROM merchants m
 WHERE m.id = #{merchantId}
   AND m.region_id = #{regionId}
   AND m.category IN ('ACCOMMODATION', 'OFFICE')

SELECT 
  FROM recommendation_requests rr
  LEFT JOIN merchants m ON m.id = rr.reference_merchant_id
  LEFT JOIN merchants sm ON sm.id = rr.secondary_reference_merchant_id
 WHERE rr.id = #{requestId}
   AND rr.user_id = #{userId}

SELECT 
  FROM recommendation_requests rr
  LEFT JOIN merchants m ON m.id = rr.reference_merchant_id
  LEFT JOIN merchants sm ON sm.id = rr.secondary_reference_merchant_id
 WHERE rr.user_id = #{userId}
   AND rr.workation_id = #{workationId}
   AND rr.recommendation_type = 'ACTIVITY'

   AND rr.reference_merchant_id = #{referenceMerchantId}

 ORDER BY rr.created_at DESC, rr.id DESC
 LIMIT 1

SELECT result.id AS recommendation_result_id, result.recommendation_request_id, result.merchant_id, result.price_score, result.preference_score, result.accessibility_score, result.rating_score, result.total_score, result.calculated_at, result.ranking, m.name AS merchant_name, m.address, m.thumbnail_url, m.price, m.rating, a.activity_type, CAST(COUNT(rv.review_id) AS UNSIGNED) AS review_count, NULL AS difficulty, (SELECT GROUP_CONCAT(t.name ORDER BY t.name ASC SEPARATOR ',') FROM merchant_tags mt INNER JOIN tags t ON t.id = mt.tag_id WHERE mt.merchant_id = m.id) AS activity_tags, EXISTS (SELECT 1 FROM bookmarks b WHERE b.users_id = (SELECT user_id FROM recommendation_requests WHERE id = #{requestId}) AND b.merchants_id = m.id AND b.is_deleted IS NULL) AS bookmarked, m.latitude, m.longitude FROM recommendation_results result JOIN merchants m ON m.id = result.merchant_id LEFT JOIN activities a ON a.merchant_id = m.id LEFT JOIN reviews rv ON rv.merchant_id = m.id AND rv.status = 'ACTIVE' WHERE result.recommendation_request_id = #{requestId}
AND (result.ranking > #{cursorRanking} OR (result.ranking = #{cursorRanking} AND result.id > #{cursorId}))
GROUP BY result.id, result.recommendation_request_id, result.merchant_id, result.price_score, result.preference_score, result.accessibility_score, result.rating_score, result.total_score, result.calculated_at, result.ranking, m.name, m.address, m.thumbnail_url, m.price, m.rating, a.activity_type, m.latitude, m.longitude ORDER BY result.ranking ASC, result.id ASC LIMIT #{limit}
